const { Issuer } = require('openid-client');
const db = require('../lib/db');
exports.callback = async (req, res) => {
  const issuer = await Issuer.discover(process.env.OIDC_ISSUER_URL);
  const client = new issuer.Client({ client_id: process.env.OIDC_CLIENT_ID });
  const tokenSet = await client.callback(process.env.OIDC_REDIRECT, client.callbackParams(req), { state: req.session.state });
  const claims = tokenSet.claims();
  let user = await db.users.findOne({ username: claims.preferred_username });
  if (!user) user = await db.users.insert({ username: claims.preferred_username, email: claims.email });
  req.session.userId = user.id;
  res.redirect('/');
};

